class Solution {
    public int beautifulSubstrings(String s, int k) {
        String vowels = "aeiou";
        int n = s.length();
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int v = 0, c = 0;
            for (int j = i; j < n; j++) {
                if (vowels.indexOf(s.charAt(j)) != -1) v++;
                else c++;
                if (v == c && (v * c) % k == 0) ans++;
            }
        }
        return ans;
    }
}

/**
 * @param {string} s
 * @param {number} k
 * @return {number}
 */
var beautifulSubstrings = function(s, k) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    const n = s.length;
    let ans = 0;
    for (let i = 0; i < n; i++) {
        let v = 0, c = 0;
        for (let j = i; j < n; j++) {
            if (vowels.has(s[j])) v++;
            else c++;
            if (v === c && (v * c) % k === 0) ans++;
        }
    }
    return ans;
};
